(function(){
  'use strict';
  const S=window.AstrisSensors,E=window.AstrisEngine,O=window.AstrisOperator,T=window.AstrisTransport,L=window.AstrisLeadtime,B=window.AstrisBenchmark,U=window.AstrisVerification,$=s=>document.querySelector(s),KEY='astris-demo-v1';
  const SERVER_MODE=location.protocol==='http:'&&['127.0.0.1','localhost'].includes(location.hostname);
  const paths={grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8M22 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75',trend:'M3 17 9 11l4 4 8-10M15 5h6v6',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',list:'M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01',download:'M12 3v12m-5-5 5 5 5-5M5 16v5h14v-5',book:'M12 6c-4-3-8-3-10-2v15c4-1 7-1 10 2 3-3 6-3 10-2V4c-4-1-7-1-10 2Zm0 0v15',plus:'M12 5v14M5 12h14',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8',activity:'M2 12h5l3-8 4 16 3-8h5',check:'m5 12 4 4L19 6',clock:'M12 8v4l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',arrow:'M5 12h14m-5-5 5 5-5 5',play:'m8 4 12 8-12 8Z',pause:'M8 5v14M16 5v14',refresh:'M20 8V3l-3 3a9 9 0 1 0 3 10M20 3h-5',moon:'M21 13a9 9 0 0 1-10-10A9 9 0 1 0 21 13Z',shield:'m12 2 9 4v6c0 6-9 10-9 10S3 18 3 12V6Zm-4 9 3 3 5-6',wifi:'M2 8a16 16 0 0 1 20 0M5 12a11 11 0 0 1 14 0M8 16a6 6 0 0 1 8 0M12 20h.01',alert:'m12 3 10 18H2ZM12 9v5m0 3h.01',thermo:'M9 14V5a3 3 0 0 1 6 0v9a5 5 0 1 1-6 0ZM12 8v10',drop:'M12 2S4 10 4 15a8 8 0 0 0 16 0c0-5-8-13-8-13Z',sun:'M12 2v2m0 16v2M2 12h2m16 0h2M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',settings:'M4 7h16M4 17h16M8 4v6m8 4v6',file:'M14 2H5v20h14V7Zm0 0v6h5M8 13h8m-8 4h6'};
  function icon(name){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.activity}"/></svg>`;}
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  Object.entries({hr:'#b599ef',bp:'#9daee9',spo2:'#80c5cb',temp:'#d8aa81',glucose:'#c0a3db',sleep:'#8da9da',mood:'#d3add3'}).forEach(([k,color])=>E.METRICS[k].color=color);
  document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
  let state=E.create(),selected='a1',metric='hr',range=60,view='overview',running=true,speed=2000,filter='active',timer,storageOK=true;
  // Only the legacy standalone file uses localStorage. HTTP mode stores operator state on the server.
  if(location.protocol==='file:'){try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved?.state?.version===1&&E.CREW.every(c=>Array.isArray(saved.state.histories?.[c.id])&&saved.state.histories[c.id].length&&typeof saved.state.histories[c.id].at(-1).ts==='number')&&saved.state.counters&&Array.isArray(saved.state.alerts)&&Array.isArray(saved.state.log)){state=saved.state;selected=E.CREW.some(c=>c.id===saved.selected)?saved.selected:'a1';running=false;}}catch{}}
  O.prepare(state);T.prepare(state);L.prepare(state);
  let verificationTab='scenarios',verificationMetric='hr',benchmarkRunning=false,benchmarkProgress='',advancing=false;
  // Demo telemetry is synchronized only through the authenticated local operator session.
  // Data remains synthetic. The astronaut endpoint returns only its own profile.
  function syncGround(){
    if(SERVER_MODE)return;
    if(location.protocol!=='http:'||location.hostname!=='127.0.0.1')return;
    const payload={now:state.now,running,speed,crew:E.CREW.map(c=>({id:c.id,history:(state.histories[c.id]||[]).slice(-80).map(p=>({ts:p.ts,quality:p.quality,hr:p.hr,sys:p.sys,dia:p.dia,spo2:p.spo2,temp:p.temp,glucose:p.glucose})),alerts:state.alerts.filter(a=>a.crewId===c.id).slice(0,30).map(a=>({id:a.id,metric:a.metric,title:a.title,severity:a.severity,origin:a.origin,ts:a.ts,lastSeen:a.lastSeen,acknowledgedAt:a.acknowledgedAt,evidenceUnavailable:a.evidenceUnavailable,resolvedAt:a.resolvedAt}))}))};
    fetch('/api/telemetry',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-Astris-Action':'1'},body:JSON.stringify(payload)}).catch(()=>{});
  }
  let remoteRevision=0,pendingWrites=0,pollPending=false,writeQueue=Promise.resolve();
  function persist(){
    if(location.protocol==='file:'){
      try{localStorage.setItem(KEY,JSON.stringify({state,selected}));}catch{if(storageOK){storageOK=false;toast('Сховище браузера недоступне. Експортуйте сесію, щоб зберегти дані.');}}
      return;
    }
    const body=JSON.stringify({state,selected,running,speed});
    pendingWrites++;
    // Serial writes preserve UI action order, including rapid pause/step/resume sequences.
    writeQueue=writeQueue.catch(()=>{}).then(async()=>{
      const r=await fetch('/api/operator/state',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-Astris-Action':'1'},body});
      if(!r.ok)throw Error('Не вдалося зберегти зміни місії (HTTP '+r.status+').');
      const result=await r.json();remoteRevision=result.revision??remoteRevision;
    }).catch(e=>{console.error('ASTRIS Ground save:',e);toast('Помилка синхронізації: '+e.message);}).finally(()=>{pendingWrites--;});
  }

  const G=(k,v)=>E.grade(k,v,state),V=(k,v)=>{if(E.value(k,v,state)==='—')return '—';const format=(x,d=0)=>Number(x).toLocaleString('uk-UA',{minimumFractionDigits:d,maximumFractionDigits:d});return k==='bp'?format(v.sys)+'/'+format(v.dia):format(S.value(v,k),['temp','spo2','sleep'].includes(k)?1:0);};
  const crew=()=>E.CREW.find(c=>c.id===selected),now=()=>E.current(state,selected);
  const formatTime=ts=>new Date(ts).toLocaleTimeString('uk-UA',{timeZone:'UTC',hour:'2-digit',minute:'2-digit'});
  const label={normal:'Без сигналів',warning:'Відхилення',critical:'Високий пріоритет',missing:'Немає даних',invalid:'Некоректні дані',stale:'Застарілі дані',future:'Мітка з майбутнього',unconfigured:'Межі не задані'};
  const metricIcon={hr:'heart',bp:'activity',spo2:'drop',temp:'thermo',glucose:'drop',sleep:'moon',mood:'sun'};
  const scenarioNames={nominal:'Штатний',hr:'Стрибок пульсу',hypoxia:'Зміна SpO₂',fever:'Зміна температури',fatigue:'Втома',offline:'Втрата телеметрії',glucose:'Зміна глюкози',drift:'Лінійний дрейф',stale:'Застарілі пакети',invalid:'Помилка даних',noise:'Шум вимірювань',spike:'Одиночний викид',gaps:'Пропуски значень',cycles:'Циклічні зміни'};
  const activeAlerts=()=>state.alerts.filter(a=>!a.resolvedAt);
  function visualStatus(id){const confirmed=E.status(state,id);if(confirmed!=='normal')return confirmed;const v=E.current(state,id);return O.telemetryMetrics().some(k=>['warning','missing','stale','invalid'].includes(G(k,v)))?'warning':'normal';}
  const pill=(status,text)=>`<span class="status-pill ${status}"><i class="status-dot ${status}"></i>${text||label[status]}</span>`;
  const avatar=c=>`<span class="avatar" style="background:${c.color}20;color:${c.color}">${c.initials}</span>`;
  function spark(id,key){const h=state.histories[id].slice(-25).map(v=>S.inspect(v,key,v.ts,S.get(state,key))).filter(r=>r.quality==='good').map(r=>r.value);if(!h.length)return `<span class="spark"></span>`;const lo=Math.min(...h)-2,hi=Math.max(...h)+2;return `<svg class="spark" viewBox="0 0 68 18" aria-hidden="true"><path stroke="${E.METRICS[key].color}" d="${h.map((v,i)=>`${i?'L':'M'}${(i/(h.length-1||1)*68).toFixed(1)} ${(16-(v-lo)/(hi-lo)*14).toFixed(1)}`).join(' ')}"/></svg>`;}
  function pageHeading(title,subtitle){return '<div class="page-heading"><div><h1>'+title+'</h1><p class="page-sub">'+subtitle+'</p></div></div>';}
  function digitalHuman(){return '<div class="model-orbit"></div><canvas id="human-canvas" data-focus="human-model" class="human-canvas" tabindex="0" role="img" aria-label="Умовна 3D-модель людини. Перетягуйте або використовуйте стрілки для обертання. Home — початковий ракурс."></canvas><div class="model-fallback">3D недоступне в цьому браузері.<br>Усі показники доступні поруч.</div>';}
  function bodyFigure(){
    const c=crew();
    return '<section class="panel anatomy-panel" aria-label="Персональна модель: '+c.name+'"><div class="person-info"><div class="profile-identity">'+personPhoto(c,'profile-headshot')+'<div><h2>'+c.name+'</h2><p>'+c.role+'<span class="person-divider"></span>'+ageLabel(c.age)+'</p></div></div></div><div class="anatomy-frame">'+digitalHuman()+'</div><div class="model-controls"><span>Перетягніть для обертання</span><div class="segmented"><button data-action="model-angle" data-angle="front">Спереду</button><button data-action="model-angle" data-angle="side">Збоку</button></div></div></section>';
  }
  function vitals(){
    const v=now(),summary=A.sourceSummary(state,selected),reports=O.reports(state,selected),configured=A.KEYS.filter(k=>{const cfg=S.get(state,k);return cfg.min!==null||cfg.max!==null;}).length;
    const cards=O.telemetryMetrics().map(k=>{const m=E.METRICS[k],g=G(k,v),note=['unconfigured','normal'].includes(g)?'':label[g];return '<button class="metric-card '+g+'" data-action="detail" data-metric="'+k+'" data-focus="metric-'+k+'" aria-label="'+m.name+': '+V(k,v)+' '+m.unit+'. '+label[g]+'. Відкрити деталі"><span class="metric-label">'+m.name+icon(metricIcon[k])+'</span><span class="metric-reading"><strong>'+V(k,v).replace('.',',')+'</strong><small>'+m.unit+'</small></span>'+(note?'<span class="metric-caption '+g+'">'+note+'</span>':'')+'</button>';}).join('');
    return '<section class="panel vitals-panel" aria-labelledby="vitals-title"><div class="panel-head"><h2 class="panel-title" id="vitals-title">Показники</h2><button class="source-state '+(summary.good===summary.total?'':'needs-attention')+'" data-action="sources" title="Перевірити час отримання даних">'+summary.good+' / '+summary.total+' актуальні</button></div>'+(summary.good<summary.total?'<p class="source-last">Останнє валідне: '+finiteTime(summary.lastValidTs)+' · '+elapsed(summary.lastValidTs)+' тому</p>':'')+'<div class="metric-grid">'+cards+'</div><div class="dashboard-vitals-foot"><button class="crew-message-link" data-action="crew-messages">'+icon('book')+'<span>Повідомлення екіпажу</span><b>'+reports.length+'</b></button><button class="dashboard-limit-link" data-action="settings" data-metric="hr">'+(configured?'Межі: '+configured+' із '+A.KEYS.length+' каналів':'Налаштувати межі')+icon('settings')+'</button></div></section>';
  }
  function dashboardAttention(){
    const signals=activeAlerts().filter(a=>a.crewId===selected).sort((a,b)=>(b.severity==='critical')-(a.severity==='critical')||b.ts-a.ts);
    const rows=signals.slice(0,2).map(a=>'<button class="attention-row" data-action="alert-detail" data-id="'+a.id+'"><span class="attention-marker '+a.severity+'">'+icon('alert')+'</span><span><b>'+esc(a.title)+'</b><small>'+esc(a.origin==='joint'?'Кілька каналів':a.metric==='sensor'?'Якість даних':E.METRICS[a.metric]?.name||'Телеметрія')+'</small></span>'+icon('arrow')+'</button>').join('');
    return '<section class="panel dashboard-attention" aria-labelledby="attention-title"><div class="panel-head"><h2 class="panel-title" id="attention-title">Потребує уваги</h2><a href="#alerts" class="attention-all">Усі сигнали'+icon('arrow')+'</a></div>'+(signals.length?'<div class="attention-list">'+rows+'</div>':'<div class="attention-empty">'+icon('check')+'<p>Активних сигналів немає</p></div>')+(signals.length>2?'<a class="attention-more" href="#alerts">Ще '+(signals.length-2)+' у центрі сигналів</a>':'')+'</section>';
  }

  function rangeControls(){return `<div class="segmented" aria-label="Період графіка">${[[15,'15 хв'],[60,'1 год'],[360,'6 год']].map(([r,t])=>`<button data-action="range" data-range="${r}" aria-pressed="${range===r}" class="${range===r?'active':''}">${t}</button>`).join('')}</div>`;}
  function simulator(){
    const sc=state.scenarios[selected]||'nominal',buttons=keys=>keys.map(key=>'<button class="scenario-btn '+(sc===key?'active':'')+'" data-action="scenario" data-scenario="'+key+'" aria-pressed="'+(sc===key)+'">'+scenarioNames[key]+'</button>').join('');
    return '<section class="panel sim-panel"><div class="sim-title"><h2>Сценарій даних</h2><span class="live-label '+(running?'':'paused')+'">'+(running?(SERVER_MODE?'СЕРВЕР ПРАЦЮЄ':'ПРАЦЮЄ'):'ПАУЗА')+'</span></div><div class="sim-controls"><button class="button primary" data-action="toggle" data-focus="toggle">'+icon(running?'pause':'play')+(running?'Пауза':'Запустити')+'</button><button class="button" data-action="step">+1 хв</button><button class="button" data-action="burst">+10 хв</button><select id="speed" aria-label="Швидкість симуляції">'+[[4000,'1 хв / 4 с'],[2000,'1 хв / 2 с'],[500,'1 хв / 0,5 с']].map(([value,title])=>'<option value="'+value+'" '+(speed===value?'selected':'')+'>'+title+'</option>').join('')+'</select></div><div class="scenarios">'+buttons(['nominal','drift','cycles','noise','spike','offline'])+'</div><details class="compact-details more-scenarios" data-persist="more-scenarios"><summary>Інші сценарії</summary><div class="scenarios">'+buttons(['hr','hypoxia','fever','glucose','stale','invalid','gaps'])+'</div></details><div class="sim-crew-report"><button class="button" data-action="simulate-report">Додати тестове повідомлення</button></div><div class="sim-foot"><button class="text-btn" data-action="reset">Скинути демо</button></div></section>';
  }
  function crewMessages(){
    const records=O.reports(state,selected);
    const body=records.length?'<div class="crew-report-list">'+records.map(p=>'<article class="crew-report"><div class="crew-report-heading"><h3>'+esc(p.authorName)+'</h3><span class="report-source">'+(p.source==='simulator'?'Тестове повідомлення':'Неперевірене зовнішнє джерело')+'</span></div><dl><div><dt>Надіслано</dt><dd>'+finiteTime(p.reportedAt)+'</dd></div><div><dt>Отримано консоллю</dt><dd>'+finiteTime(p.receivedAt)+'</dd></div></dl><p>'+esc(p.text)+'</p><div class="report-values">'+(Number.isFinite(p.values?.sleep)?'<span>Сон зі слів автора <b>'+decimal(p.values.sleep,1)+' год</b></span>':'')+(Number.isFinite(p.values?.mood)?'<span>Самопочуття <b>'+p.values.mood+' / 5</b></span>':'')+'</div><p class="note-small">Зазначений автор — '+esc(p.authorName)+'. Особу не перевірено.</p></article>').join('')+'</div>':'<div class="empty-state"><h3>Повідомлень поки немає</h3><p>Тут з’являться повідомлення астронавта.</p></div>';
    modal('Повідомлення екіпажу',crew().name+' · UTC симуляції',body,'<button class="button primary" data-action="close">Закрити</button>');
  }
  function operatorTimeline(a){return '<section class="operator-lifecycle"><h3>Історія сигналу</h3><ol><li><span>Виявлено</span><b>'+finiteTime(a.ts)+'</b></li><li><span>Взято в роботу</span><b>'+(a.acknowledgedAt?finiteTime(a.acknowledgedAt):'Ще ні')+'</b></li><li><span>Завершено</span><b>'+(a.resolvedAt?finiteTime(a.resolvedAt):a.evidenceUnavailable?'Бракує даних':'Сигнал активний')+'</b></li></ol><p>«Взяти в роботу» фіксує ознайомлення, але не закриває відхилення.</p></section>';}
  function overview(){return '<div class="page-heading dashboard-heading"><h1>Огляд</h1><div class="dashboard-header-actions"><div class="dashboard-crew">'+selectCrew()+'</div></div></div><div class="dashboard-layout">'+bodyFigure()+'<div class="dashboard-data">'+vitals()+dashboardAttention()+'</div></div>';}
  function demoView(){
    const tabs=[['scenarios','Сценарії'],['delivery','Доставка'],['leadtime','Завчасність'],['control','Точність прогнозу']];
    const controls=verificationTab==='control'?'':'<div class="verification-toolbar">'+selectCrew()+(verificationTab==='leadtime'?'<label>Показник<select id="verification-metric">'+A.KEYS.map(k=>'<option value="'+k+'" '+(k===verificationMetric?'selected':'')+'>'+S.TYPES[k].name+'</option>').join('')+'</select></label>':'')+(verificationTab==='scenarios'?'':'<button class="button" data-action="toggle">'+(running?'Пауза':'Запустити')+'</button><button class="button" data-action="step">+1 хв</button><button class="button" data-action="burst">+10 хв</button>')+'<span class="simulation-clock">'+formatTime(state.now)+' UTC</span></div>';
    return '<div class="page-heading"><h1>Демо</h1><button class="button" data-action="export">Зберегти результати</button></div><div class="verification-tabs" role="group" aria-label="Інструменти демо">'+tabs.map(([key,label])=>'<button class="button '+(verificationTab===key?'primary':'')+'" data-action="verification-tab" data-tab="'+key+'" aria-pressed="'+(verificationTab===key)+'">'+label+'</button>').join('')+'</div>'+controls+(verificationTab==='scenarios'?simulator():U.section(state,selected,verificationTab,verificationMetric,benchmarkRunning,benchmarkProgress));
  }
  function crewView(){return '<div class="page-heading"><div><h1>Екіпаж</h1><p class="page-sub"></p></div></div><div class="crew-photo-grid">'+E.CREW.map(c=>{const v=E.current(state,c.id);return '<article class="panel crew-photo-card"><button class="crew-photo-open" data-action="select-crew" data-id="'+c.id+'" aria-label="Відкрити профіль: '+c.name+'"><div class="crew-photo-wrap">'+personPhoto(c,'crew-portrait')+'<span class="crew-photo-status">'+pill(visualStatus(c.id))+'</span></div><div class="crew-photo-info"><span class="crew-member-code">ARES / '+c.id.slice(1).padStart(2,'0')+'</span><h2>'+c.name+'</h2><p>'+c.role+' · '+ageLabel(c.age)+'</p><div class="crew-photo-metrics">'+['hr','spo2','temp'].map(k=>'<div><span>'+E.METRICS[k].name+'</span><strong>'+V(k,v)+'<small>'+E.METRICS[k].unit+'</small></strong></div>').join('')+'</div><span class="crew-open-label">Відкрити профіль '+icon('arrow')+'</span></div></button></article>';}).join('')+'</div>';}
  function selectCrew(){return `<label for="crew-filter">Астронавт</label><select id="crew-filter">${E.CREW.map(c=>`<option value="${c.id}" ${selected===c.id?'selected':''}>${c.name}</option>`).join('')}</select>`;}
  function alertsView(){
    const list=state.alerts.filter(a=>filter==='all'||(filter==='new'?!a.resolvedAt&&!a.acknowledgedAt:filter==='active'?!a.resolvedAt:!!a.resolvedAt)).sort((a,b)=>(!b.resolvedAt)-(!a.resolvedAt)||b.ts-a.ts);
    const empty=filter==='new'?'Нових сигналів немає':filter==='resolved'?'Завершених сигналів немає':filter==='all'?'Сигналів немає':'Активних сигналів немає';
    return '<div class="page-heading"><h1>Сигнали</h1><button class="button" data-action="open-log">'+icon('list')+'Журнал</button></div><div class="view-toolbar"><span class="muted">'+list.length+' сигналів</span><div class="segmented">'+[['new','Нові'],['active','Активні'],['resolved','Завершені'],['all','Усі']].map(([key,title])=>'<button data-action="filter" data-filter="'+key+'" class="'+(filter===key?'active':'')+'" aria-pressed="'+(filter===key)+'">'+title+'</button>').join('')+'</div></div><div class="alert-list">'+(list.length?list.map(alertCard).join(''):'<section class="panel empty-state"><h2>'+empty+'</h2><p>Поточні показники й задані межі доступні в огляді.</p></section>')+'</div>';
  }
  function alertCard(a){const c=E.CREW.find(c=>c.id===a.crewId);return `<article class="panel alert-card ${a.resolvedAt?'resolved':''}"><div class="alert-sign ${a.resolvedAt?'resolved':a.severity}">${icon(a.resolvedAt?'check':'alert')}</div><div><h3>${a.title}</h3><p>${c.name} <span class="footer-dot">·</span> ${a.origin==='joint'?'Кілька каналів':a.metric==='sensor'?'Якість даних':E.METRICS[a.metric].name}</p><div class="alert-status">${a.resolvedAt?'Завершено о '+formatTime(a.resolvedAt):a.acknowledgedAt?'В роботі':'Новий сигнал'}</div><div class="alert-buttons"><button class="button small" data-action="alert-detail" data-id="${a.id}">Деталі ${icon('arrow')}</button>${!a.acknowledgedAt&&!a.resolvedAt?`<button class="button small accent" data-action="ack" data-id="${a.id}">Взяти в роботу</button>`:''}</div></div><div class="alert-at">${formatTime(a.ts)} UTC${!a.resolvedAt?pill(a.severity):pill('normal','Завершено')}<b>${esc(a.lastValue)}</b></div></article>`;}
  function openLog(){
    const text=message=>message.replace('Завершено дослідницький сигнал:','Завершено:').replace('Спільний дослідницький сигнал:','Одночасні зміни:').replace('Дослідницький сигнал:','Сигнал:');
    const rows=items=>items.map(l=>'<div class="log-row"><time>'+formatTime(l.ts)+'<small>'+new Date(l.ts).toISOString().slice(0,10)+'</small></time>'+icon({alert:'alert',action:'check',recovery:'shield',scenario:'settings',system:'activity','crew-report':'book'}[l.type])+'<p>'+esc(text(l.message))+'</p></div>').join('');
    modal('Журнал',state.log.length+' подій збережено · UTC симуляції','<div class="compact-log">'+rows(state.log.slice(0,15))+(state.log.length>15?'<details class="compact-details"><summary>Раніше · '+(state.log.length-15)+' подій</summary>'+rows(state.log.slice(15))+'</details>':'')+'</div>','<button class="button" data-action="export">Зберегти сесію</button><button class="button primary" data-action="close">Закрити</button>');
  }
  const A=window.AstrisAnalytics;
  const decimal=(v,n=1)=>v===null||!Number.isFinite(v)?'—':v.toFixed(n).replace('.',',');
  const signed=(v,n=1)=>v===null?'—':(v>0?'+':'')+decimal(v,n);
  function ageLabel(age){const last=age%10,teen=age%100;return age+' '+(teen>=11&&teen<=14?'років':last===1?'рік':last>=2&&last<=4?'роки':'років');}
  function personPhoto(c,cls=''){const src=window.ASTRIS_PORTRAITS?.[c.id];return src?`<img class="${cls}" src="${src}" alt="Згенерований портрет: ${c.name}" loading="lazy" decoding="async">`:avatar(c);}
  let graphState=null,chartOptions={sma:true,ewma:false,band:false,forecast:true,uncertainty:true};
  function analysisChart(q){
    if(!q.points.length){graphState=null;return `<div class="empty-state">${icon('wifi')}<h2>Немає валідних точок у вибраному вікні</h2><p>Помилкові дані не підміняються нулями. Відновіть потік або змініть період.</p></div>`;}
    const b=q.baseline,c=q.config,small=window.innerWidth<760,w=small?660:1050,h=small?390:350,L=65,R=30,T=32,B=40,pw=w-L-R,ph=h-T-B;
    const useForecast=chartOptions.forecast&&q.forecast.eligible,end=useForecast?q.to+c.forecastMinutes*60000:q.to,extent=q.points.map(p=>p.y);
    if(useForecast){extent.push(...q.forecast.points.map(p=>p.y));if(chartOptions.uncertainty)extent.push(...q.forecast.points.flatMap(p=>[p.lower,p.upper]).filter(Number.isFinite));}if(chartOptions.band&&b.scale>0)extent.push(b.mean-c.sigmaThreshold*b.scale,b.mean+c.sigmaThreshold*b.scale);
    let lo=Math.min(...extent),hi=Math.max(...extent),pad=Math.max((hi-lo)*.14,hi===lo?Math.max(Math.abs(hi)*.02,.01):.001);lo-=pad;hi+=pad;if(!Number.isFinite(lo)||!Number.isFinite(hi)||!Number.isFinite(hi-lo)){graphState=null;return '<div class="empty-state">Числовий діапазон перевищує можливості графіка. Перевірте масштаб і одиниці джерела.</div>';}
    const x=ts=>L+(ts-q.from)/(end-q.from||60000)*pw,y=v=>T+(hi-v)/(hi-lo)*ph;
    const line=rows=>{let pen=false,d='';for(const p of rows){if(!Number.isFinite(p.y)){pen=false;continue;}d+=`${pen?'L':'M'}${x(p.ts).toFixed(2)},${y(p.y).toFixed(2)} `;pen=true;}return d;};
    const intervalPoints=q.forecast.points.filter(p=>Number.isFinite(p.lower)&&Number.isFinite(p.upper)),intervalPath=intervalPoints.length>1?'M'+intervalPoints.map(p=>x(p.ts).toFixed(2)+','+y(p.upper).toFixed(2)).join(' L')+' L'+[...intervalPoints].reverse().map(p=>x(p.ts).toFixed(2)+','+y(p.lower).toFixed(2)).join(' L')+' Z':'';
    const items=[...q.points.map(p=>({...p,kind:'Факт'})),...(useForecast?q.forecast.points.filter(p=>p.ts>q.to).map(p=>({...p,kind:'Прогноз'})):[])];graphState={q,items,w,L,R,end,activeIndex:-1,pinned:false};
    const anomalyTimes=new Set(q.anomalies.map(p=>p.ts));
    return `<div class="analysis-chart-shell"><svg class="analysis-chart" data-analysis-chart tabindex="0" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(S.TYPES[q.key].name)}: вимірювань: ${q.n}, ${q.anomalies.length} статистичних аномалій; ${useForecast?'окремий прогноз на '+c.forecastMinutes+' хв':'прогноз не показано'}. Стрілки ліворуч і праворуч вибирають точки." aria-describedby="chart-help">${useForecast?`<rect x="${x(q.to)}" y="${T}" width="${x(end)-x(q.to)}" height="${ph}" fill="#83619f" opacity=".1"/><text x="${x(q.to)+7}" y="${T-12}" fill="#d7b28a" font-size="${small?15:10}">+${c.forecastMinutes} хв</text><line x1="${x(q.to)}" x2="${x(q.to)}" y1="${T}" y2="${T+ph}" stroke="#b78e69" stroke-dasharray="4 5" opacity=".6"/>`:''}${chartOptions.band&&b.scale>0?`<rect x="${L}" y="${y(b.mean+c.sigmaThreshold*b.scale)}" width="${x(q.to)-L}" height="${y(b.mean-c.sigmaThreshold*b.scale)-y(b.mean+c.sigmaThreshold*b.scale)}" fill="#9775bd" opacity=".08"/>`:''}${[0,1,2,3,4].map(i=>{const yy=T+ph*i/4;return `<line x1="${L}" x2="${w-R}" y1="${yy}" y2="${yy}" stroke="#302a3c" stroke-dasharray="3 6"/><text x="${L-12}" y="${yy+4}" fill="#9887a7" font-size="${small?17:11}" text-anchor="end">${decimal(hi-i/4*(hi-lo),q.key==='temp'?2:1)}</text>`;}).join('')}${[['min',c.min],['max',c.max]].filter(([,v])=>v!==null&&v>=lo&&v<=hi).map(([k,v])=>`<line x1="${L}" x2="${w-R}" y1="${y(v)}" y2="${y(v)}" stroke="#d5a66f" stroke-dasharray="7 5" opacity=".7"/><text x="${L+8}" y="${y(v)-7}" fill="#d5a66f" font-size="${small?15:10}">${k} ${v}</text>`).join('')}${useForecast&&chartOptions.uncertainty?`<path class="forecast-band" d="${intervalPath}" fill="#efbf83" opacity=".14"/>`:""}<path d="${line(q.series)}" stroke="#c6ade9" fill="none" stroke-width="2"/>${chartOptions.sma?`<path d="${line(q.sma)}" stroke="#79c6c8" fill="none" stroke-width="2.3"/>`:''}${chartOptions.ewma?`<path d="${line(q.ewma)}" stroke="#8aa6dc" fill="none" stroke-width="1.7" stroke-dasharray="3 4"/>`:''}${useForecast?`<path d="${line(q.forecast.points)}" stroke="#efbf83" fill="none" stroke-width="2.5" stroke-dasharray="7 5"/>${q.forecast.points.filter(p=>p.ts>q.to).map(p=>`<circle cx="${x(p.ts)}" cy="${y(p.y)}" r="3.5" fill="#17131d" stroke="#efbf83" stroke-width="1.5"/>`).join('')}`:''}${q.points.filter(p=>anomalyTimes.has(p.ts)).map(p=>`<circle cx="${x(p.ts)}" cy="${y(p.y)}" r="${small?4.8:3.8}" fill="#ed98ad" stroke="#21151f" stroke-width="1.2"><title>${esc('z = '+p.z.toFixed(3)+'; '+new Date(p.ts).toISOString())}</title></circle>`).join('')}${[0,1,2,3,4].map(i=>`<text x="${L+pw*i/4}" y="${h-10}" fill="#93809f" font-size="${small?16:10}" text-anchor="${i===0?'start':i===4?'end':'middle'}">${formatTime(q.from+(end-q.from)*i/4)}</text>`).join('')}</svg><div id="analysis-tooltip" class="analysis-tooltip" role="status" aria-live="polite" hidden></div></div>`;
  }
  function chartTooltip(index){
    if(!graphState?.items.length)return;const g=graphState,i=Math.max(0,Math.min(index,g.items.length-1));if(g.activeIndex===i)return;g.activeIndex=i;
    const p=g.items[i],el=$('#analysis-tooltip');if(!el)return;const smooth=g.q.sma.find(s=>s.ts===p.ts),time=new Date(p.ts).toLocaleTimeString('uk-UA',{timeZone:'UTC',hour:'2-digit',minute:'2-digit',second:'2-digit'});
    el.innerHTML=`<strong>${p.kind} · ${time} UTC</strong><span>${decimal(p.y,3)} ${esc(g.q.config.unit)}</span>${p.kind==='Факт'?`<small>z: ${signed(p.z,2)}${Number.isFinite(smooth?.y)?' · SMA: '+decimal(smooth.y,3):''}</small>`:`<small>${rangeLabel(p.intervalMethod)}${p.lower===null?"":": "+decimal(p.lower,3)+" … "+decimal(p.upper,3)+" "+esc(g.q.config.unit)}<br>${esc(g.q.forecast.model?.name||"Прогноз")} · не факт</small>`}`;el.hidden=false;
    const shell=el.parentElement,pointX=(g.L+(p.ts-g.q.from)/(g.end-g.q.from||60000)*(g.w-g.L-g.R))/g.w*shell.clientWidth;el.style.left=Math.max(8,Math.min(pointX-80,shell.clientWidth-el.offsetWidth-8))+'px';
  }
  let analysisMode='channel',compareA='hr',compareB='bp';
  const finiteTime=ts=>Number.isFinite(ts)?formatTime(ts)+' UTC':'—';
  const elapsed=ts=>Number.isFinite(ts)?Math.max(0,(state.now-ts)/1000).toFixed(0)+' с':'—';
  const qualityPill=q=>pill(q.quality==='good'?'normal':['future','invalid'].includes(q.quality)?'invalid':q.quality,q.quality==='good'?'Дані актуальні':label[q.quality]||'Помилка даних');
  function analysisHeading(){return '<div class="page-heading"><h1>Аналіз</h1><div class="analysis-heading-actions"><button class="button" data-action="methods">Формули</button><button class="button accent" data-action="'+(analysisMode==='compare'?'research-settings':'settings')+'" data-metric="'+(A.KEYS.includes(metric)?metric:'hr')+'">'+icon('settings')+(analysisMode==='compare'?'Налаштування':'Межі')+'</button></div></div><div class="research-modes" role="group" aria-label="Вид аналізу">'+[['channel','Графік'],['compare','Порівняння']].map(([mode,title])=>'<button data-action="research-mode" data-mode="'+mode+'" aria-pressed="'+(analysisMode===mode)+'" class="'+(analysisMode===mode?'active':'')+'">'+title+'</button>').join('')+'</div>';}
  function analysisToolbar(){return `<div class="view-toolbar analytics-toolbar">${selectCrew()}<div class="segmented">${[[15,'15 хв'],[60,'1 год'],[360,'6 год']].map(([r,title])=>`<button data-action="range" data-range="${r}" class="${r===range?'active':''}" aria-pressed="${r===range}">${title}</button>`).join('')}</div></div>`;}
  function rangeLabel(method){return {'empirical-95':'95% діапазон історичних помилок','conditional-student-t':'95% умовний інтервал МНК','observed-error-envelope':'Діапазон спостережених помилок','unavailable':'Недостатньо даних для діапазону'}[method]||'Діапазон прогнозу';}
  function forecastSummary(q){
    const f=q.forecast,v=f.validation,end=f.points.at(-1),u=esc(q.config.unit),model=f.model,selection=f.selection;
    if(!f.eligible)return '<section class="panel forecast-lab"><h2>Прогноз недоступний</h2><p>'+esc(f.reason)+'</p></section>';
    return '<section class="panel forecast-lab"><div class="forecast-head"><div><h2>Прогноз на '+f.horizonMinutes+' хв</h2><div class="forecast-trend">'+esc(f.trend.title)+'</div><p>'+esc(model.name)+(f.trend.periodMinutes?' · період близько '+decimal(f.trend.periodMinutes,1)+' хв':'')+(selection?.provisional?' · замало історії для порівняння моделей':'')+'</p></div><div class="forecast-last"><span>'+finiteTime(end.ts)+'</span><strong>'+decimal(end.y,q.key==='temp'?2:1)+'<small>'+u+'</small></strong><span class="forecast-interval">'+(end.lower===null?'Діапазон ще не визначено':decimal(end.lower,2)+' … '+decimal(end.upper,2)+' '+u)+'</span></div></div><details class="compact-details" data-persist="forecast-validation"><summary>Оцінка прогнозу</summary><div class="validation-grid">'+[['RMSE',v?.eligible?decimal(v.rmse,3):'—',u],['MAE',v?.eligible?decimal(v.mae,3):'—',u],['RMSE останнього значення',v?.eligible?decimal(v.naiveRmse,3):'—',u],['Покриття діапазонів',v?.eligible?decimal(v.coverage,1):'—','%']].map(([name,value,unit])=>'<div><span>'+name+'</span><strong>'+value+'<small>'+unit+'</small></strong></div>').join('')+'</div><p class="validation-note">'+(v?.eligible?v.n+' перевірок за наступними вимірюваннями. Діапазон доступний для '+v.intervalTests+' із них.':'Є '+(v?.n??0)+' перевірок; для оцінки потрібно щонайменше '+(v?.minTests??5)+'.')+' Це результат на минулих даних, а не гарантія майбутньої точності.</p>'+(selection?'<h3>Вибір моделі</h3><p>'+esc(selection.reason)+'</p><div class="table-scroll"><table><thead><tr><th>Модель</th><th>RMSE для вибору</th><th>MAE</th><th>Перевірок</th></tr></thead><tbody>'+selection.scores.map(row=>'<tr class="'+(row.id===model.id?'selected-model':'')+'"><td>'+esc(row.name)+'</td><td>'+decimal(row.rmse,3)+'</td><td>'+decimal(row.mae,3)+'</td><td>'+row.n+'</td></tr>').join('')+'</tbody></table></div><p>Кандидати порівнюються на однакових минулих цілях. Оцінки вище перевіряють увесь алгоритм вибору.</p>':'')+'<h3>Діапазон</h3><p>'+rangeLabel(end.intervalMethod)+'. '+(end.calibrationN?end.calibrationN+' завершених помилок для цього горизонту. ':'')+'Зміна режиму може збільшити похибку.'+(end.degenerateInterval?' Нульові історичні помилки дали нульову ширину діапазону; похибка реального датчика невідома.':'')+'</p></details></section>';
  }
  function comparisonChart(q){
    if(!q.pairs.length||q.pairs.every(p=>p.zA===null||p.zB===null))return '<div class="empty-state">Немає зіставлених точок із визначеними z. Перевірте базу, часовий допуск і період.</div>';
    const small=window.innerWidth<760,w=small?660:1000,h=small?360:300,L=60,R=24,T=25,B=40,valid=q.pairs.flatMap(p=>[p.zA,p.zB]).filter(Number.isFinite),lo=Math.min(-1,...valid)-.5,hi=Math.max(1,...valid)+.5,from=Math.max(q.a.from,q.b.from),to=q.a.to,x=t=>L+(t-from)/(to-from||60000)*(w-L-R),y=z=>T+(hi-z)/(hi-lo)*(h-T-B),line=(field,segment)=>{let d='',previous=null;for(const p of q.pairs){if(!Number.isFinite(p[field])){previous=null;continue;}const join=previous&&p[segment]===previous[segment]&&(p.ts-previous.ts)/1000<=Math.min(q.a.config.maxGapSeconds,q.b.config.maxGapSeconds);d+=(join?'L':'M')+x(p.ts).toFixed(2)+','+y(p[field]).toFixed(2)+' ';previous=p;}return d;};
    return `<svg class="comparison-chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="Два фізіологічні ряди у z-одиницях особистої бази; кореляція не доводить причинності">${[0,1,2,3].map(i=>`<line x1="${L}" x2="${w-R}" y1="${T+i*(h-T-B)/3}" y2="${T+i*(h-T-B)/3}" stroke="#302a3c" stroke-dasharray="3 5"/><text x="${L-10}" y="${T+i*(h-T-B)/3+4}" text-anchor="end" fill="#9887a7" font-size="${small?17:11}">${decimal(hi-i*(hi-lo)/3,1)}</text>`).join('')}<path d="${line('zA','segmentA')}" fill="none" stroke="#c6ade9" stroke-width="2.4"/><path d="${line('zB','segmentB')}" fill="none" stroke="#79c6c8" stroke-width="2.4"/>${q.pairs.filter(p=>Number.isFinite(p.zA)&&Number.isFinite(p.zB)).map(p=>`<circle cx="${x(p.ts)}" cy="${y(p.zA)}" r="3" fill="#c6ade9"><title>${finiteTime(p.tsA)}: ${S.TYPES[q.a.key].name} ${p.a} ${q.a.config.unit}; ${finiteTime(p.tsB)}: ${S.TYPES[q.b.key].name} ${p.b} ${q.b.config.unit}; розбіжність міток ${p.skewSeconds} с</title></circle>`).join('')}${[0,1,2,3,4].map(i=>`<text x="${L+i*(w-L-R)/4}" y="${h-10}" text-anchor="${i===0?'start':i===4?'end':'middle'}" fill="#9887a7" font-size="${small?17:11}">${formatTime(from+i*(to-from)/4)}</text>`).join('')}</svg>`;
  }
  function jointSummary(group){return `<section class="panel joint-summary"><div class="panel-head"><h2 class="panel-title">Одночасні відхилення</h2><span class="signal-tag">${group.active?'Каналів: '+group.n:'Немає збігу за правилом'}</span></div>${group.active?`<p>${group.members.map(p=>`<b>${S.TYPES[p.key].name}</b>: ${decimal(p.value,3)} ${esc(p.unit)} · z ${signed(p.z,2)} · ${finiteTime(p.ts)}`).join('<br>')}</p><code>Каналів ${group.n} ≥ ${group.minConcurrent}; Δt ${decimal(group.spreadSeconds,1)} с ≤ ${group.coincidenceSeconds} с</code><p>Статистична одночасність не встановлює причини. Кореляція не використовується як доказ несправності або діагноз.</p>`:`<p>Потрібні щонайменше ${group.minConcurrent} актуальні канали з |z| за власним порогом і мітками в межах ${group.coincidenceSeconds} с. ${group.assessable?'За доступними даними умову не виявлено.':'Для частини каналів немає валідного актуального z; повна оцінка недоступна.'}</p>`}</section>`;}
  function comparisonView(){
    const q=A.compare(state,selected,compareA,compareB,range),options=(value,except)=>A.KEYS.filter(k=>k!==except).map(k=>'<option value="'+k+'" '+(k===value?'selected':'')+'>'+S.TYPES[k].name+'</option>').join('');
    const pairs='<div class="table-scroll"><table><thead><tr><th>Час</th><th>'+S.TYPES[compareA].name+' · '+esc(q.a.config.unit)+'</th><th>Час</th><th>'+S.TYPES[compareB].name+' · '+esc(q.b.config.unit)+'</th><th>Різниця, с</th></tr></thead><tbody>'+q.pairs.slice(-10).map(p=>'<tr><td>'+finiteTime(p.tsA)+'</td><td>'+decimal(p.a,3)+'</td><td>'+finiteTime(p.tsB)+'</td><td>'+decimal(p.b,3)+'</td><td>'+decimal(p.skewSeconds,1)+'</td></tr>').join('')+'</tbody></table></div>';
    return analysisHeading()+analysisToolbar()+'<div class="comparison-selectors"><label>Перший показник<select id="compare-a">'+options(compareA,null)+'</select></label><span>↔</span><label>Другий показник<select id="compare-b">'+options(compareB,compareA)+'</select></label></div><div class="comparison-kpis">'+[['Спільних вимірювань',q.n,''],['Повнота',decimal(q.coverage??null,1),'%'],['Кореляція значень',decimal(q.levelR,3),''],['Кореляція змін',decimal(q.changeR,3),'']].map(([name,value,unit])=>'<article class="panel"><span>'+name+'</span><strong>'+value+'<small>'+unit+'</small></strong></article>').join('')+'</div>'+(!q.eligible?'<p class="protocol-notice">'+esc(q.reason)+'</p>':'')+'<section class="panel comparison-panel"><div class="panel-head"><h2 class="panel-title">Зміни відносно особистої бази</h2></div><div class="comparison-legend"><span><i></i>'+S.TYPES[compareA].name+'</span><span><i></i>'+S.TYPES[compareB].name+'</span></div>'+comparisonChart(q)+'<p>Обидва показники приведено до шкали z. Кореляція показує зв’язок, але не пояснює його причину.</p><details class="compact-details" data-persist="comparison-pairs"><summary>Останні 10 пар вимірювань</summary>'+pairs+'<p>Допуск часу: '+A.researchConfig(state).pairToleranceSeconds+' с. Кореляцію змін обчислено за '+(q.changesN??0)+' послідовними парами; пропуски не з’єднуються.</p></details></section>'+(q.group.active?jointSummary(q.group):'');
  }
  function sourcesContent(){const summary=A.sourceSummary(state,selected);return '<div class="source-grid">'+summary.channels.map(q=>'<article class="panel source-card"><div><h3>'+S.TYPES[q.key].name+'</h3>'+qualityPill(q)+'</div><dl><div><dt>Останній пакет</dt><dd>'+finiteTime(q.latestTs)+'</dd></div><div><dt>Останнє валідне</dt><dd>'+finiteTime(q.lastValidTs)+'</dd></div><div><dt>Вік / строк актуальності</dt><dd>'+elapsed(q.lastValidTs)+' / '+q.config.maxAgeSeconds+' с</dd></div></dl><button class="text-btn" data-action="inspect-sensor" data-metric="'+q.key+'">Відкрити графік</button></article>').join('')+'</div>';}
  function jointEvidence(e){return e?.members?'<div class="table-scroll"><table><thead><tr><th>Канал</th><th>Значення</th><th>z</th><th>Час</th></tr></thead><tbody>'+e.members.map(p=>'<tr><td>'+S.TYPES[p.key].name+'</td><td>'+decimal(p.value,3)+' '+esc(p.unit)+'</td><td>'+signed(p.z,3)+'</td><td>'+finiteTime(p.ts)+'</td></tr>').join('')+'</tbody></table></div>':'';}
  function sourceModal(){modal('Актуальність показників',crew().name+' · '+finiteTime(state.now),sourcesContent(),'<button class="button primary" data-action="close">Зрозуміло</button>');}
  function researchSettings(){const c=A.researchConfig(state),field=(name,title,value,extra='')=>`<label class="field">${title}<input name="${name}" type="number" value="${value}" ${extra} required></label>`;modal('Параметри порівняння','Дослідницькі правила, не нормативи безпеки',`<form id="research-settings-form"><div class="config-grid">${field('pairToleranceSeconds','Допуск зіставлення міток · с',c.pairToleranceSeconds,'min="0" step="0.1"')}${field('minPairs','Мінімум пар для кореляції',c.minPairs,'min="3" max="200" step="1"')}${field('minCoverage','Повнота спільного вікна · %',c.minCoverage*100,'min="1" max="100" step="1"')}${field('coincidenceSeconds','Вікно одночасних відхилень · с',c.coincidenceSeconds,'min="0" max="600" step="1"')}${field('minConcurrent','Мінімум одночасних каналів',c.minConcurrent,'min="2" max="6" step="1"')}${field('persistencePoints','Пакетів для стійкого відхилення',c.persistencePoints,'min="3" max="10" step="1"')}</div><p class="note-small">За замовчуванням зіставляються лише однакові часові мітки. Допуск не може перевищувати половину меншого налаштованого інтервалу пакетів. Парні значення не інтерполюються й не використовуються повторно. Налаштування застосовуються до всього екіпажу.</p><p class="form-error" id="research-config-error" role="alert"></p><div class="modal-footer"><button class="button" type="button" data-action="close">Скасувати</button><button class="button primary" type="submit">Зберегти</button></div></form>`);}
  function analyticsView(){graphState=null;return analysisMode==='compare'?comparisonView():singleAnalysisView();}

  function singleAnalysisView(){
    const key=A.KEYS.includes(metric)?metric:'hr',q=A.analyze(state,selected,key,range,{audit:true}),b=q.baseline,c=q.config,unit=esc(c.unit);
    const kpis=[['Середнє',decimal(q.mean,2),unit],['Мінімум',decimal(q.min,2),unit],['Максимум',decimal(q.max,2),unit],['Швидкість зміни',q.rate?signed(q.rate.value,2):'—',unit+' / хв']];
    const controls='<div class="view-toolbar analytics-toolbar">'+selectCrew()+'<label class="sensor-select">Показник<select id="analysis-sensor">'+A.KEYS.map(k=>'<option value="'+k+'" '+(k===key?'selected':'')+'>'+S.TYPES[k].name+'</option>').join('')+'</select></label>'+rangeControls()+'</div>';
    const warnings=q.warnings.length?'<section class="panel analysis-signals"><div class="panel-head"><h2 class="panel-title">Що змінилося</h2></div>'+q.warnings.map(w=>'<article><h3>'+esc(w.title)+'</h3><details class="compact-details"><summary>Розрахунок</summary><code>'+esc(w.equation)+'</code><p>'+esc(w.detail)+'</p></details></article>').join('')+'</section>':'';
    const details='<details class="panel analysis-extra compact-details" data-persist="analysis-statistics"><summary>Статистика та якість даних</summary><div class="extra-stat-grid">'+[['Стандартне відхилення s',decimal(q.sd,3)+' '+unit],['Відхилення від бази z',signed(q.z,2)],['Середнє бази μ',decimal(b.mean,3)+' '+unit],['Стандартне відхилення бази',decimal(b.sd,3)+' '+unit],['Точок у базі',b.n],['Повнота',decimal(q.coverage,1)+'%']].map(([name,value])=>'<div><span>'+name+'</span><strong>'+value+'</strong></div>').join('')+'</div><p>База: перші '+b.n+' валідних вимірювань. Шкала σеф = '+decimal(b.scale,3)+'. Поріг |z| = '+c.sigmaThreshold+'.</p><p>Валідних інтервалів: '+q.validBins+' із '+q.expected+'. Некоректних пакетів: '+q.issues.invalid+', пропусків: '+q.issues.missing+'. Дублів у збереженій історії: '+q.issues.duplicates+'. Помилкових міток: '+q.issues.invalidTimestamp+', майбутніх: '+q.issues.future+'.</p><p>Інтервал '+c.expectedIntervalSeconds+' с; актуальність до '+c.maxAgeSeconds+' с. Остання пара для швидкості: '+(q.rate?decimal(q.rate.dtSeconds,1)+' с':'недоступна')+'.</p><p>'+esc(q.pattern.title)+'. '+esc(q.pattern.detail)+'</p></details>';
    return analysisHeading()+controls+'<div class="channel-policy"><span>'+esc(S.limitsText(state,key))+'</span>'+qualityPill(q)+'</div><div class="analysis-kpis">'+kpis.map(([name,value,u])=>'<article class="panel analysis-kpi"><span>'+name+'</span><strong>'+value+'<small>'+u+'</small></strong></article>').join('')+'</div><section class="panel analysis-plot-panel"><div class="panel-head"><h2 class="panel-title">'+S.TYPES[key].name+'</h2><label class="horizon-control">Прогноз<select id="forecast-horizon" aria-label="Горизонт прогнозу">'+[1,3,5,10,15].map(n=>'<option value="'+n+'" '+(c.forecastMinutes===n?'selected':'')+'>+'+n+' хв</option>').join('')+'</select></label></div><div class="chart-switches">'+[['sma','Згладжування'],['forecast','Прогноз'],['uncertainty','Діапазон']].map(([option,label])=>'<label><input type="checkbox" data-chart-option="'+option+'" '+(chartOptions[option]?'checked':'')+'>'+label+'</label>').join('')+'<details class="chart-extra compact-details" data-persist="chart-options"><summary>Ще</summary><label><input type="checkbox" data-chart-option="ewma" '+(chartOptions.ewma?'checked':'')+'>EWMA · α 0,2</label><label><input type="checkbox" data-chart-option="band" '+(chartOptions.band?'checked':'')+'>База ±'+c.sigmaThreshold+'σеф</label></details></div>'+analysisChart(q)+'<p id="chart-help" class="chart-help">Наведіть на точку, щоб побачити значення.</p></section>'+forecastSummary(q)+warnings+details;
  }
  function settings(key){
    if(!A.KEYS.includes(key))key=A.KEYS.includes(metric)?metric:'hr';const c=S.get(state,key);
    const field=(name,title,value,extra='')=>`<label class="field">${title}<input name="${name}" type="number" step="any" value="${value??''}" ${extra}></label>`;
    modal('Параметри каналу',S.TYPES[key].name+' · '+c.unit,`<form id="sensor-config-form" data-key="${key}"><label class="field">Тип показника<select id="config-sensor">${A.KEYS.map(k=>`<option value="${k}" ${k===key?'selected':''}>${S.TYPES[k].name} · ${S.TYPES[k].unit}</option>`).join('')}</select></label><p class="note-small">Застосовується до цього типу показника в усьому екіпажі. Джерелом допустимих меж має бути ваша специфікація або протокол. Порожнє поле вимикає відповідне правило.</p><h3>Допустимі межі · користувацькі</h3><div class="config-grid">${field('min','Нижня межа · '+c.unit,c.min,'placeholder="Не задано"')}${field('max','Верхня межа · '+c.unit,c.max,'placeholder="Не задано"')}${field('maxRate','Ліміт |Δx/Δt| · '+c.unit+'/хв',c.maxRate,'placeholder="Не задано"')}${field('confirmationSamples','Пакетів для підтвердження межі',c.confirmationSamples,'min="1" max="20" required')}</div><h3>Математичні параметри</h3><div class="config-grid">${field('sigmaThreshold','Поріг |z|',c.sigmaThreshold,'min="0.01" required')}${field('sigmaFloor','Мінімальна шкала σеф · '+c.unit,c.sigmaFloor,'min="0" required')}${field('movingAveragePoints','SMA · кількість точок',c.movingAveragePoints,'min="2" max="60" required')}${field('forecastMinutes','Горизонт прогнозу · хв',c.forecastMinutes,'min="1" max="15" required')}${field('forecastLookbackMinutes','Пам’ять адаптивного прогнозу · хв',c.forecastLookbackMinutes,'min="15" max="120" required')}${field('fitWindowMinutes','Вікно МНК-тренду · хв',c.fitWindowMinutes,'min="5" max="120" required')}${field('minCoverage','Мінімальна повнота для прогнозу · %',c.minCoverage*100,'min="1" max="100" required')}</div><h3>Час і якість</h3><div class="config-grid">${field('expectedIntervalSeconds','Очікуваний інтервал пакетів · с',c.expectedIntervalSeconds,'min="0.01" required')}${field('maxAgeSeconds','TTL актуальності · с',c.maxAgeSeconds,'min="0.01" required')}${field('maxGapSeconds','Найбільший послідовний розрив · с',c.maxGapSeconds,'min="0.01" required')}</div><p class="note-small">Початкові часові параметри призначені для демосимулятора з одним пакетом за хвилину. Це не норми реального датчика. Базова модель потребує щонайменше ${c.minFitPoints} точок за ${c.minFitSpanMinutes} хв; AR(2) — ≥12 точок. Для автоматичного вибору потрібні ≥8 спільних перевірок.</p><p id="config-error" class="form-error" role="alert"></p><div class="modal-footer"><button type="button" class="button" data-action="clear-limits">Очистити межі</button><button class="button primary" type="submit">Зберегти</button></div></form>`);
  }
  function methods(){const key=A.KEYS.includes(metric)?metric:'hr',q=A.analyze(state,selected,key,range),c=q.config;modal('Формули та методи',S.TYPES[key].name+' · '+crew().name,`<div class="method-item"><h3>Середнє, мінімум, максимум і стандартне відхилення</h3><code>x̄ = Σxᵢ / n; min(x); max(x)</code><code>s = √[Σ(xᵢ − x̄)² / (n − 1)]</code><p>Використовуються лише валідні унікальні часові мітки вибраного періоду. За n &lt; 2 стандартне відхилення не визначається.</p></div><div class="method-item"><h3>Швидкість зміни</h3><code>v = (x₂ − x₁) / [(t₂ − t₁) / 60 000]</code><p>Часові мітки — мілісекунди; знаменник переводиться у хвилини. Пара не використовується через помилку, пропуск або розрив понад ${c.maxGapSeconds} с.</p></div><div class="method-item"><h3>Згладжування</h3><code>SMAₜ = (xₜ + … + xₜ₋ₖ₊₁) / k; k = ${c.movingAveragePoints}</code><code>EWMAₜ = 0,2xₜ + 0,8EWMAₜ₋₁</code><p>SMA потребує повного вікна k точок. Обидва ряди починаються заново після невалідного пакета або великого розриву.</p></div><div class="method-item"><h3>Статистичні аномалії</h3><code>σеф = max(s бази, користувацька шкала)</code><code>z = (x − μ бази) / σеф; |z| ≥ ${c.sigmaThreshold}</code><p>База фіксується за першими до 30 валідними пакетами. За нульової шкали z не обчислюється. Поріг статистичний і конфігурований, не фізіологічний норматив.</p></div><div class="method-item"><h3>Регресія та короткий прогноз</h3><code>β = Σ[(tᵢ − t̄)(xᵢ − x̄)] / Σ(tᵢ − t̄)²</code><code>α = x̄ − βt̄; ŷ(t+h) = α + β(t+h)</code><code>R² = 1 − SSE / SST; RMSE = √(SSE / n)</code><p>Навчання: останнє послідовне вікно до ${c.fitWindowMinutes} хв, ≥${c.minFitPoints} точок і ≥${c.minFitSpanMinutes} хв, повнота ≥${c.minCoverage*100}%. Горизонт ${c.forecastMinutes} хв. Пунктир — прогноз, суцільна лінія — факт. При втраті актуальності прогноз блокується. RMSE — похибка підгонки, а не перевірена похибка майбутнього.</p></div><div class="method-item"><h3>Повнота та інформаційні сигнали</h3><code>Повнота = зайняті валідні часові інтервали / очікувані × 100%</code><p>Дублікати не збільшують повноту. Значення NaN, Infinity, текст, неправильні одиниці, майбутні та некоректні часові мітки виключаються. Кожен сигнал містить формулу, параметри та значення; допустимі межі початково вимкнено.</p></div><div class="method-item"><h3>Похибка на наступних вимірюваннях</h3><code>eᵢ = ŷᵢ − yᵢ; MAE = Σ|eᵢ|/m; RMSE = √[Σeᵢ²/m]</code><p>На кожній історичній точці початку модель навчається лише на минулому. Оцінка окрема для вибраного горизонту; пропуски виключаються. Порівняння — з прогнозом «останнє значення». Це перевірка на синтетичній історії.</p></div><div class="method-item"><h3>Адаптивне прогнозування</h3><code>AR(2): uₜ = a + φ₁uₜ₋₁ + φ₂uₜ₋₂; u=(x−μ)/s</code><code>Голт: ŷ(h)=ℓ+b·φ(1−φ^(h/Δ))/(1−φ), φ=0,9</code><p>Порівнюються останнє значення, МНК, згасаючий тренд і AR(2). Кожен історичний вибір бачить тільки попередні результати. Потрібні ≥8 спільних перевірок на заданому горизонті, перевага складнішій моделі за зменшення RMSE базової ≥10%. AR(2) потребує регулярного потоку й стабільних коренів; нестійкий результат відхиляється. Пам’ять прогнозу налаштовується окремо від періоду графіка.</p></div><div class="method-item"><h3>Діапазон адаптивного прогнозу</h3><code>q = sorted(|e|)[ceil((n+1)·0,95)]; межі = ŷ ± q</code><p>Використовуються тільки помилки, цільові факти яких були відомі на момент прогнозу. Для 95% рангу потрібно ≥19 помилок. За 5–18 показано спостережений максимум без заяви про 95%. Часові залежності й зміна режиму можуть порушувати майбутнє покриття.</p></div><div class="method-item"><h3>Лише для лінійної моделі: умовний інтервал</h3><code>ŷ ± t₀․₉₇₅,ₙ₋₂ · √[SSE/(n−2)] · √[1+1/n+(t−t̄)²/Sxx]</code><p>95% інтервал нового спостереження за припущеннями лінійної моделі. Припущення незалежних нормальних залишків і сталої дисперсії не підтверджені. Нульові залишки можуть дати вироджену смугу; це не нульова похибка реального сенсора.</p></div><div class="method-item"><h3>Порівняння каналів</h3><code>r = Σ[(x−x̄)(y−ȳ)] / √[Σ(x−x̄)² Σ(y−ȳ)²]</code><p>Одноразове зіставлення часових міток без інтерполяції, окремо r рівнів і швидкостей. Для сталого ряду r не визначається. Одночасні відхилення визначаються за |z| кожного каналу та часовим вікном, а не кореляцією. Причинність не встановлюється.</p></div><p class="note-small"><a href="https://www.itl.nist.gov/div898/handbook/pmd/section4/pmd431.htm" target="_blank" rel="noopener">NIST: метод найменших квадратів ↗</a>. Прототип не є сертифікованою системою безпеки.</p>`,`<button class="button primary" data-action="close">Зрозуміло</button>`);}

  function render(){
    const focus=document.activeElement?.dataset.focus,scrollTop=window.scrollY;
    $('#nav-alerts').textContent=activeAlerts().length;$('#nav-alerts').dataset.empty=String(activeAlerts().length===0);$('#nav-alerts').dataset.critical=String(activeAlerts().some(a=>a.severity==='critical'));
    const names={overview:'Огляд',crew:'Екіпаж',alerts:'Сигнали',analytics:'Аналіз',demo:'Демо',accounts:'Акаунти'};
    document.querySelectorAll('nav a').forEach(a=>{a.title=names[a.dataset.view];a.classList.toggle('active',a.dataset.view===view);if(a.dataset.view===view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
    // Do not replace an open native select while the user is choosing an option.
    if(document.activeElement?.tagName==='SELECT'||document.activeElement?.closest('#transport-form')||document.querySelector('.human-canvas.dragging'))return;
    const expanded=Array.from(document.querySelectorAll('main details[data-persist][open]')).map(d=>d.dataset.persist);
    window.AstrisHuman.detach();
    $('#main').innerHTML=({overview,crew:crewView,alerts:alertsView,analytics:analyticsView,demo:demoView})[view]();
    document.querySelectorAll('main details[data-persist]').forEach(d=>{if(expanded.includes(d.dataset.persist))d.open=true;});
    if(advancing)document.querySelectorAll('[data-action=step],[data-action=burst],[data-action=toggle]').forEach(b=>b.disabled=true);
    if(view==='overview')window.AstrisHuman.mount($('#human-canvas')); 
    if(focus){const el=document.querySelector(`[data-focus="${focus}"]`);if(el)el.focus({preventScroll:true});}
    if(window.scrollY!==scrollTop)window.scrollTo(0,scrollTop);
  }
  function tick(){E.tick(state);A.sync(state);L.observe(state);persist();render();}
  function startTimer(){clearInterval(timer);if(SERVER_MODE){persist();return;}if(running)timer=setInterval(tick,speed);syncGround();}
  async function pollMission(){
    if(!SERVER_MODE||pollPending||pendingWrites||advancing||benchmarkRunning)return;
    pollPending=true;
    try{
      const response=await fetch('/api/operator/state?since='+remoteRevision,{credentials:'same-origin',cache:'no-store'});
      if(response.status===401){location.replace('/login.html');return;}
      if(!response.ok)throw Error('HTTP '+response.status);
      const update=await response.json();
      if(update.saved?.state&&pendingWrites===0){
        state=update.saved.state;
        running=update.saved.running!==false;
        speed=Number(update.saved.speed)||2000;
        O.prepare(state);T.prepare(state);L.prepare(state);
        render();
      }
      if(pendingWrites===0)remoteRevision=update.revision||remoteRevision;
    }catch(e){console.warn('ASTRIS Ground live sync:',e.message);}
    finally{pollPending=false;}
  }
  function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),5000);}
  function modal(title,subtitle,body,footer=''){const d=$('#modal');$('#modal-content').innerHTML=`<div class="modal-top"><div><h2>${title}</h2>${subtitle?`<small>${subtitle}</small>`:''}</div><button class="modal-close" data-action="close" aria-label="Закрити">×</button></div>${body}${footer?`<div class="modal-footer">${footer}</div>`:''}`;if(!d.open)d.showModal();}
  function detail(key,alertId){
    const a=alertId?state.alerts.find(a=>a.id===alertId):null,id=a?a.crewId:selected,k=a?a.metric:key,c=E.CREW.find(c=>c.id===id),v=E.current(state,id),m=E.METRICS[k];
    if(a){const e=a.evidence;modal(a.title,c.name+' · '+(a.origin==='joint'?'одночасні відхилення каналів':a.origin==='analysis'?'математичний сигнал':a.origin==='legacy'?'архів старих демо-правил':'користувацьке правило'),`<div class="detail-reading"><div><small>Зафіксоване значення · ${formatTime(a.lastSeen||a.ts)} UTC</small><strong>${esc(a.lastValue)} <small>${m?.unit||''}</small></strong></div>${pill(a.resolvedAt?'normal':'warning',a.resolvedAt?'Завершено':'Сигнал')}</div>${e?`<h3>Розрахунок</h3><code class="rule-equation">${esc(e.equation)}</code><p>${esc(e.detail)}</p>${e.rate?`<p class="note-small">x₁ = ${e.rate.fromValue}; x₂ = ${e.rate.toValue}; Δt = ${decimal(e.rate.dtSeconds,3)} с.</p>`:''}`:'<p>Сигнал створено попередньою версією прототипу. Його старі фіксовані межі більше не використовуються.</p>'}${a.origin==='joint'?jointEvidence(e):''}${operatorTimeline(a)}${a.evidenceUnavailable?'<div class="protocol-notice">Бракує нових даних для перевірки. Сигнал залишається активним.</div>':''}${a.resolutionReason?`<p class="note-small">Причина завершення: ${esc(a.resolutionReason)}</p>`:''}<p class="research-notice">Розрахунок збережено на момент сигналу.</p>`,`${!a.resolvedAt&&!a.acknowledgedAt?`<button class="button accent" data-action="ack" data-id="${a.id}">Взяти в роботу</button>`:''}<button class="button primary" data-action="close">Зрозуміло</button>`);return;}
    if(!A.KEYS.includes(k)){crewMessages();return;}
    if(m){metric=k;render();}const g=E.guidance(k,G(k,v));modal(m.name,c.name,`<div class="detail-reading"><div><strong>${V(k,v)}</strong> <small>${m.unit}</small></div>${pill(G(k,v))}</div><p>${g.why}</p><h3>Правило для цього показника</h3><p>${esc(E.limitsText(state,k))}. </p><p class="note-small">Пакет: ${formatTime(v.ts)} UTC. Застарілий або некоректний показник не відображається як актуальне число.</p><ol>${g.steps.map(x=>`<li>${x}</li>`).join('')}</ol><div class="research-notice">Межі мають відповідати вашому протоколу.</div>`,`${A.KEYS.includes(k)?`<button class="button" data-action="settings" data-metric="${k}">Параметри каналу</button><a class="button" href="#analytics" data-action="close">До аналізу</a>`:''}<button class="button primary" data-action="close">Зрозуміло</button>`);
  }



  function guide(){modal('Про ASTRIS','Наземна консоль моніторингу','<p>Огляд показує поточні вимірювання обраного астронавта. В «Екіпажі» можна змінити профіль, в «Аналізі» — переглянути графік і прогноз, у «Сигналах» — перевірити відхилення та відкрити журнал.</p><p>У «Демо» зібрано сценарії датчиків, затримки доставки, оцінку завчасності та перевірку прогнозів на окремому наборі даних.</p><h3>Дані та обмеження</h3><p>Екіпаж вигаданий, портрети згенеровано, показники змодельовано. Реальні датчики та зв’язок не підключені. Повідомлення екіпажу показані окремо від вимірювань; автор не проходить перевірку особи.</p><p>Межі задає користувач. Система виявляє статистичні зміни, не встановлює діагнозів і не є сертифікованим медичним засобом. Для реальної роботи потрібна перевірка фахівцями.</p><p>Дані зберігаються в цьому браузері. Час наведено в UTC симуляції. Зберегти сесію можна в розділі «Демо».</p>','<button class="button primary" data-action="close">Закрити</button>');}
  function exportData(){const payload={application:'ASTRIS',version:'1.7',transportSimulation:state.transport,leadTimeEvaluation:state.leadtime,controlEvaluation:state.controlEvaluation||null,consoleRole:'ground',crewReports:state.crewReports,legacyNonTelemetryFields:['sleep','mood'],dataType:'synthetic-demo-only',exportedAt:new Date().toISOString(),missionTime:new Date(state.now).toISOString(),timeScale:'one tick = one simulated minute',analysisWindowMinutes:range,analysisSnapshot:Object.fromEntries(E.CREW.map(c=>[c.id,Object.fromEntries(A.KEYS.map(k=>{const q=A.analyze(state,c.id,k,range,{audit:true});return [k,{current:q.current,quality:q.quality,qualityReason:q.qualityReason,issues:q.issues,latestTs:q.latestTs,lastValidTs:q.lastValidTs,lastKnownValue:q.lastKnownValue,pattern:q.pattern,ageSeconds:q.ageSeconds,baseline:q.baseline,z:q.z,mean:q.mean,min:q.min,max:q.max,sd:q.sd,rate:q.rate,trend:q.fit,forecast:q.forecast,anomalies:q.anomalies,warnings:q.warnings,config:q.config,coverage:q.coverage,valid:q.n,expected:q.expected}];}))])),researchSettings:A.researchConfig(state),jointSnapshots:Object.fromEntries(E.CREW.map(c=>[c.id,A.compare(state,c.id,compareA,compareB,range)])),analysisMethods:{predictionInterval:'horizon-specific prequential absolute errors; finite sample 95% rank only for n>=19; observed-error envelope for n>=5; conditional Student t fallback for linear model; assumptions unverified',validation:'rolling-origin, forward-only, horizon-specific; MAE/RMSE/bias, last-value benchmark, observed interval coverage',correlation:'Pearson levels and actual-time rates; one-to-one timestamp alignment; no causal inference',mean:'sum(x)/n',sampleSD:'sqrt(sum((x-mean)^2)/(n-1))',rate:'delta x / delta t in minutes',sma:'rolling mean of configured k points',ewmaAlpha:0.2,z:'(x-fixedMean)/max(fixedSD,configuredFloor)',forecast:'past-only rolling-origin selection among persistence, actual-time OLS, damped Holt and regular-cadence stable AR(2); no random future values',forecastSafety:'research only; not certified',limits:'user-configured; disabled by default'},medicalDisclaimer:'Demonstration rules; not a medical device or a diagnosis. Requires flight surgeon validation.',crew:E.CREW.map(({sleep,mood,...profile})=>profile),sources:E.SOURCES,metrics:Object.fromEntries(Object.entries(E.METRICS).filter(([key])=>A.KEYS.includes(key))),state};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`astris-demo-${new Date(state.now).toISOString().slice(0,16).replace(/:/g,'-')}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('Сесію збережено у JSON.');}
  document.addEventListener('click',async event=>{const btn=event.target.closest('[data-action]');if(!btn)return;const act=btn.dataset.action,id=btn.dataset.id;
    if(advancing&&['step','burst','toggle','scenario','transport-preset'].includes(act))return;
    if(act==='open-log')openLog();
    if(act==='verification-tab'){verificationTab=btn.dataset.tab;render();}
    if(act==='transport-preset'){const presets={direct:{delayMinutes:0,variationMinutes:0,dropEvery:0},delay:{delayMinutes:4,variationMinutes:0,dropEvery:0},reorder:{delayMinutes:0,variationMinutes:6,dropEvery:0},loss:{delayMinutes:0,variationMinutes:0,dropEvery:5}};T.configure(state,selected,presets[btn.dataset.preset]);E.log(state,'action','Змінено симульований канал доставки: '+crew().name+'.');persist();render();toast('Параметри доставки змінено.');}
    if(act==='run-control'){if(benchmarkRunning)return;const target=state,wasRunning=running;benchmarkRunning=true;benchmarkProgress='0 / 6';running=false;startTimer();render();try{const report=await B.run((n,total)=>{benchmarkProgress=n+' / '+total;if(state===target)render();});if(state===target){state.controlEvaluation=report;E.log(state,'action','Виконано контрольну перевірку '+report.version+'.');persist();toast('Контрольну перевірку завершено. Результати доступні для експорту.');}}catch(error){toast('Не вдалося завершити перевірку: '+error.message);}finally{benchmarkRunning=false;if(state===target){running=wasRunning;startTimer();render();}}}
    if(act==='crew-messages')crewMessages();
    if(act==='simulate-report'){O.simulate(state,selected);persist();render();toast('Тестове повідомлення додано.');}
    if(act==='sources')sourceModal();
    if(act==='research-mode'){analysisMode=btn.dataset.mode;render();}
    if(act==='research-settings')researchSettings();
    if(act==='inspect-sensor'){metric=btn.dataset.metric;analysisMode='channel';if($('#modal').open)$('#modal').close();if(view!=='analytics')location.hash='analytics';else render();}
    if(act==='guide')guide();
    if(act==='methods')methods();
    if(act==='settings')settings(btn.dataset.metric);
    if(act==='clear-limits'){const f=$('#sensor-config-form');for(const n of ['min','max','maxRate'])f.elements[n].value='';}
    if(act==='burst'){const target=state,wasRunning=running;advancing=true;running=false;startTimer();render();try{for(let i=0;i<10&&state===target;i++){E.tick(state);A.sync(state);L.observe(state);render();await new Promise(resolve=>setTimeout(resolve,0));}if(state===target){persist();toast('Додано 10 хвилин.');}}finally{advancing=false;if(state===target){running=wasRunning;startTimer();render();}}}
    if(act==='model-angle')window.AstrisHuman.setAngle(btn.dataset.angle);
    if(act==='select-crew'){selected=id;persist();if(view!=='overview')location.hash='overview';else render();}
    if(act==='toggle'){running=!running;startTimer();render();toast(running?'Симуляцію запущено для всього екіпажу.':'Симуляцію призупинено. Час місії зупинено.');}
    if(act==='step'){tick();toast('Додано 1 хвилину.');}
    if(act==='scenario'){E.scenario(state,selected,btn.dataset.scenario);persist();render();toast(`${scenarioNames[btn.dataset.scenario]}: ${crew().name}. Застосується з наступного такту.`);}
    if(act==='range'){range=Number(btn.dataset.range);render();}
    if(act==='chart-metric'){metric=btn.dataset.metric;render();}
    if(act==='detail')detail(btn.dataset.metric);
    if(act==='alert-detail')detail(null,Number(id));
    if(act==='ack'){E.acknowledge(state,Number(id));persist();render();if($('#modal').open)$('#modal').close();toast('Сигнал взято в роботу.');}
    if(act==='filter'){filter=btn.dataset.filter;render();}
    if(act==='close')$('#modal').close();
    if(act==='export')exportData();
    if(act==='reset')modal('Почати демо заново?','Очищення локальної синтетичної сесії',`<p>Телеметрія, сигнали, повідомлення екіпажу й журнал у цьому браузері повернуться до початкового стану. За потреби спершу експортуйте сесію.</p>`,`<button class="button" data-action="export">Експортувати</button><button class="button danger" data-action="confirm-reset">Скинути демо</button>`);
    if(act==='confirm-reset'){state=E.create();O.prepare(state);T.prepare(state);L.prepare(state);A.references(state);A.sync(state);selected='a1';running=true;speed=2000;metric='hr';persist();startTimer();$('#modal').close();render();toast('Демо повернуто до початкового стану.');}
  });
  document.addEventListener('change',event=>{const el=event.target;if(el.id==='analysis-sensor'){metric=el.value;el.blur();render();return;}if(el.id==='verification-metric'){verificationMetric=el.value;el.blur();render();return;}if(el.id==='compare-a'||el.id==='compare-b'){if(el.id==='compare-a'){compareA=el.value;if(compareB===compareA)compareB=A.KEYS.find(k=>k!==compareA);}else compareB=el.value;el.blur();render();return;}if(el.id==='config-sensor'){settings(el.value);return;}if(el.id==='forecast-horizon'){E.configure(state,A.KEYS.includes(metric)?metric:'hr',{forecastMinutes:Number(el.value)});A.sync(state);L.observe(state);el.blur();persist();render();return;}if(el.dataset.chartOption){chartOptions[el.dataset.chartOption]=el.checked;render();return;}if(el.id==='speed'){speed=Number(el.value);el.blur();startTimer();render();}if(el.id==='crew-filter'){selected=el.value;el.blur();persist();render();}});
  document.addEventListener('submit',event=>{if(event.target.id==='transport-form'){event.preventDefault();try{T.configure(state,selected,Object.fromEntries([...new FormData(event.target)].map(([k,v])=>[k,Number(v)])));E.log(state,'action','Змінено параметри симульованої доставки: '+crew().name+'.');document.activeElement?.blur();persist();render();toast('Параметри доставки збережено.');}catch(error){$('#transport-error').textContent=error.message;}return;}if(event.target.id==='research-settings-form'){event.preventDefault();const draft=Object.fromEntries(new FormData(event.target));draft.minCoverage=Number(draft.minCoverage)/100;try{A.configureResearch(state,draft);A.sync(state);L.observe(state);persist();$('#modal').close();render();toast('Дослідницькі правила порівняння збережено.');}catch(error){$('#research-config-error').textContent=error.message;}return;}if(event.target.id==='sensor-config-form'){event.preventDefault();const form=event.target,data=Object.fromEntries(new FormData(form));data.minCoverage=Number(data.minCoverage)/100;try{E.configure(state,form.dataset.key,data);A.sync(state);L.observe(state);persist();$('#modal').close();render();toast('Межі та параметри збережено.');}catch(error){$('#config-error').textContent=error.message;}return;}});
  $('#guide-btn').addEventListener('click',guide);
  if(location.protocol==='file:')document.querySelectorAll('.astris-account-link,.astris-auth-controls').forEach(el=>el.hidden=true);
  $('#astris-logout')?.addEventListener('click',async()=>{
    await fetch('/api/auth/logout',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-Astris-Action':'1'},body:'{}'});
    location.replace('/login.html');
  });
  $('#modal').addEventListener('click',event=>{if(event.target===$('#modal')){const r=event.target.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)event.target.close();}});
  document.addEventListener('pointermove',event=>{const svg=event.target.closest?.('[data-analysis-chart]');if(!svg||!graphState||graphState.pinned)return;const g=graphState,r=svg.getBoundingClientRect(),u=(event.clientX-r.left)/r.width,t=g.q.from+((u*g.w-g.L)/(g.w-g.L-g.R))*(g.end-g.q.from);let best=0;for(let i=1;i<g.items.length;i++)if(Math.abs(g.items[i].ts-t)<Math.abs(g.items[best].ts-t))best=i;chartTooltip(best);});
  document.addEventListener('pointerout',event=>{const svg=event.target.closest?.('[data-analysis-chart]');if(svg&&!svg.contains(event.relatedTarget)&&!graphState?.pinned){const tip=$('#analysis-tooltip');if(tip)tip.hidden=true;if(graphState)graphState.activeIndex=-1;}});
  document.addEventListener('click',event=>{if(event.target.closest?.('[data-analysis-chart]')&&graphState)graphState.pinned=!graphState.pinned;});
  document.addEventListener('keydown',event=>{if(!event.target.matches?.('[data-analysis-chart]')||!graphState)return;const g=graphState;if(!['ArrowLeft','ArrowRight','Home','End','Escape'].includes(event.key))return;event.preventDefault();if(event.key==='Escape'){const tip=$('#analysis-tooltip');if(tip)tip.hidden=true;g.pinned=false;g.activeIndex=-1;return;}const initial=g.activeIndex<0?Math.max(0,g.items.findLastIndex(p=>p.kind==='Факт')):g.activeIndex;let index=initial;if(event.key==='ArrowLeft')index--;if(event.key==='ArrowRight')index++;if(event.key==='Home')index=0;if(event.key==='End')index=g.items.length-1;g.pinned=true;chartTooltip(index);});

  let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(render,120);});
  function readRoute(){const hash=location.hash.slice(1);if(hash==='trends'){view='analytics';analysisMode='channel';}else if(hash==='log'){view='alerts';}else if(hash==='simulator'||hash==='verification'){view='demo';verificationTab=hash==='simulator'?'scenarios':'delivery';}else view=['overview','crew','alerts','analytics','demo'].includes(hash)?hash:'overview';return hash;}
  window.addEventListener('hashchange',()=>{const route=readRoute();render();window.scrollTo(0,0);if(route==='log')openLog();});
  const initialRoute=readRoute();
  async function bootstrap(){
    if(SERVER_MODE){
      try{
        const r=await fetch('/api/operator/state',{credentials:'same-origin'});
        if(r.status===401||r.status===403){location.replace('/login.html');return;}
        if(r.ok){const snapshot=await r.json();remoteRevision=snapshot.revision||0;const stored=snapshot.saved;
          if(stored?.state?.version===1&&E.CREW.every(c=>Array.isArray(stored.state.histories?.[c.id]))){state=stored.state;selected=E.CREW.some(c=>c.id===stored.selected)?stored.selected:'a1';running=stored.running!==false;speed=Number(stored.speed)||2000;}
        }
      }catch(e){console.warn('ASTRIS: локальна сесія не завантажена',e.message);}
      try{localStorage.removeItem(KEY);}catch{}
    }
    O.prepare(state);T.prepare(state);L.prepare(state);
    A.references(state);A.sync(state);L.observe(state);render();
    if(SERVER_MODE){if(remoteRevision===0)persist();setInterval(pollMission,900);pollMission();}
    else startTimer();
    if(initialRoute==='log')openLog();
    if(location.protocol==='file:')toast('Автономна демоверсія без входу. Для акаунтів запустіть npm.cmd start.');
  }
  bootstrap();
  if(location.protocol==='https:'&&'serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
})();

